import fs from 'fs';
import fsPromises from 'fs/promises';
import os from 'os';
import path from 'path';
import crypto from 'crypto';
import { ProjectStorage } from './ProjectStorage';
import { simpleGit, type SimpleGit, type SimpleGitOptions } from 'simple-git';
import { INTERNAL_GIT_IDENTITY_ARGS } from '../utils/internalGitIdentity';
import { createLogger } from '../utils/logger';

const log = createLogger('TreeStore');

const GIT_BLOCK_TIMEOUT_MS = 120_000;
const STORE_INDEX_FILE_ENV = 'GIT_INDEX_FILE';
const GIT_OPTS: Partial<SimpleGitOptions> = {
  timeout: { block: GIT_BLOCK_TIMEOUT_MS },
  allowEnvironment: [STORE_INDEX_FILE_ENV],
  unsafe: { allowUnsafeConfigPaths: true },
};

const STORE_DIRNAME = 'store.git';
const CACHE_TREES_SUBPATH = 'trees';
const VARIANT_REF_PREFIX = 'refs/variants';
const BASE_REF_PREFIX = 'refs/bases';

const IDENTITY_ARGS = INTERNAL_GIT_IDENTITY_ARGS;

const STORE_EXCLUDES = ['.rivet/', '.DS_Store', 'Thumbs.db', '*.swp'];

const SAFE_REF_SEGMENT = /^[A-Za-z0-9_-]+$/;
const assertSafeRefSegment = (value: string, name: string): void => {
  if (!SAFE_REF_SEGMENT.test(value)) {
    throw new Error(
      `TreeStore: invalid ${name} '${value}' — must match ${SAFE_REF_SEGMENT}`,
    );
  }
};

export interface TreePutResult {
  ref: string;
  commitSha: string;
  treeSha: string;
}

export interface TreeRefInfo {
  commitSha: string;
  treeSha: string;
}

export class TreeStore {
  private readonly opQueues = new Map<string, Promise<unknown>>();

  constructor(readonly storage: ProjectStorage = new ProjectStorage()) {}

  storeDir(projectPath: string): string {
    return path.join(
      this.storage.resolve(projectPath).dataDirectory,
      STORE_DIRNAME,
    );
  }

  cacheRoot(projectPath: string): string {
    return path.join(
      this.storage.resolve(projectPath).cacheDirectory,
      CACHE_TREES_SUBPATH,
    );
  }

  variantRef(sessionId: string, variantId: string): string {
    assertSafeRefSegment(sessionId, 'sessionId');
    assertSafeRefSegment(variantId, 'variantId');
    return `${VARIANT_REF_PREFIX}/${sessionId}/${variantId}`;
  }

  baseRef(sessionId: string): string {
    assertSafeRefSegment(sessionId, 'sessionId');
    return `${BASE_REF_PREFIX}/${sessionId}`;
  }

  hasStore(projectPath: string): boolean {
    return fs.existsSync(path.join(this.storeDir(projectPath), 'HEAD'));
  }

  async putTree(args: {
    projectPath: string;
    sourceDir: string;
    ref: string;
    message: string;
    parentSha?: string;
  }): Promise<TreePutResult> {
    return this.enqueue(args.projectPath, () => this.putTreeLocked(args));
  }

  private async putTreeLocked(args: {
    projectPath: string;
    sourceDir: string;
    ref: string;
    message: string;
    parentSha?: string;
  }): Promise<TreePutResult> {
    const store = await this.ensureStore(args.projectPath);
    const indexFile = path.join(
      os.tmpdir(),
      `rivet-treestore-index-${process.pid}-${crypto.randomUUID()}`,
    );
    try {
      const git = this.git(args.sourceDir, indexFile);
      await git.raw([
        ...IDENTITY_ARGS,
        '--git-dir',
        store,
        '--work-tree',
        args.sourceDir,
        'add',
        '-A',
      ]);
      const treeSha = (
        await git.raw([...IDENTITY_ARGS, '--git-dir', store, 'write-tree'])
      ).trim();
      const commitSha = (
        await git.raw([
          ...IDENTITY_ARGS,
          '--git-dir',
          store,
          'commit-tree',
          treeSha,
          ...(args.parentSha ? ['-p', args.parentSha] : []),
          '-m',
          args.message,
        ])
      ).trim();
      await git.raw(['--git-dir', store, 'update-ref', args.ref, commitSha]);
      return { ref: args.ref, commitSha, treeSha };
    } finally {
      await fsPromises.rm(indexFile, { force: true });
    }
  }

  async putBase(args: {
    projectPath: string;
    sessionId: string;
    baseDir: string;
  }): Promise<TreePutResult> {
    const ref = this.baseRef(args.sessionId);
    return this.enqueue(args.projectPath, async () => {
      const existing = await this.resolveRef(args.projectPath, ref);
      if (existing) return { ref, ...existing };
      return this.putTreeLocked({
        projectPath: args.projectPath,
        sourceDir: args.baseDir,
        ref,
        message: `rivet base: session ${args.sessionId}`,
      });
    });
  }

  async resolveRef(
    projectPath: string,
    ref: string,
  ): Promise<TreeRefInfo | null> {
    if (!this.hasStore(projectPath)) return null;
    const store = this.storeDir(projectPath);
    try {
      const git = this.git(this.storeDir(projectPath));
      const commitSha = (
        await git.raw(['--git-dir', store, 'rev-parse', '--verify', ref])
      ).trim();
      const treeSha = (
        await git.raw([
          '--git-dir',
          store,
          'rev-parse',
          '--verify',
          `${ref}^{tree}`,
        ])
      ).trim();
      return { commitSha, treeSha };
    } catch {
      return null;
    }
  }

  async diff(
    projectPath: string,
    fromRef: string,
    toRef: string,
  ): Promise<string> {
    const store = this.storeDir(projectPath);
    return this.git(this.storeDir(projectPath)).raw([
      '--git-dir',
      store,
      'diff',
      '--binary',
      fromRef,
      toRef,
    ]);
  }

  async diffFiles(args: {
    projectPath: string;
    fromRef: string;
    toRef: string;
    files: string[];
    pathPrefix: string;
  }): Promise<string> {
    if (args.files.length === 0) return '';
    const store = this.storeDir(args.projectPath);
    return this.git(store).raw([
      '--literal-pathspecs',
      '--git-dir',
      store,
      'diff',
      '--binary',
      `--src-prefix=a/${args.pathPrefix}`,
      `--dst-prefix=b/${args.pathPrefix}`,
      args.fromRef,
      args.toRef,
      '--',
      ...args.files,
    ]);
  }

  async changedFilesCount(
    projectPath: string,
    fromRef: string,
    toRef: string,
  ): Promise<number> {
    const store = this.storeDir(projectPath);
    const out = await this.git(this.storeDir(projectPath)).raw([
      '--git-dir',
      store,
      'diff',
      '--name-only',
      fromRef,
      toRef,
    ]);
    return out.split('\n').filter((line) => line.trim().length > 0).length;
  }

  async extractToCache(args: {
    projectPath: string;
    treeSha: string;
    commitish: string;
  }): Promise<string> {
    assertSafeRefSegment(args.treeSha, 'treeSha');
    const cacheDir = path.join(this.cacheRoot(args.projectPath), args.treeSha);
    if (fs.existsSync(cacheDir)) return cacheDir;
    return this.enqueue(args.projectPath, async () => {
      if (fs.existsSync(cacheDir)) return cacheDir;
      const store = this.storeDir(args.projectPath);
      const tmpDir = `${cacheDir}.tmp-${process.pid}-${crypto.randomUUID()}`;
      const indexFile = path.join(
        os.tmpdir(),
        `rivet-treestore-extract-${process.pid}-${crypto.randomUUID()}`,
      );
      try {
        await fsPromises.mkdir(tmpDir, { recursive: true });
        const git = this.git(store, indexFile);
        await git.raw(['--git-dir', store, 'read-tree', args.treeSha]);
        await git.raw([
          '--git-dir',
          store,
          '--work-tree',
          tmpDir,
          'checkout-index',
          '-a',
          '-f',
        ]);
        await fsPromises.rename(tmpDir, cacheDir);
        return cacheDir;
      } catch (err) {
        await fsPromises.rm(tmpDir, { recursive: true, force: true });
        throw err;
      } finally {
        await fsPromises.rm(indexFile, { force: true });
      }
    });
  }

  async materializeWorktree(projectPath: string, ref: string): Promise<string> {
    return this.enqueue(projectPath, async () => {
      const store = this.storeDir(projectPath);
      const worktreePath = path.join(
        os.tmpdir(),
        `rivet-replay-${process.pid}-${crypto.randomUUID()}`,
      );
      await this.git(this.storeDir(projectPath)).raw([
        '--git-dir',
        store,
        'worktree',
        'add',
        '--detach',
        worktreePath,
        ref,
      ]);
      return worktreePath;
    });
  }

  async removeWorktree(
    projectPath: string,
    worktreePath: string,
  ): Promise<void> {
    await this.enqueue(projectPath, async () => {
      const store = this.storeDir(projectPath);
      try {
        await this.git(this.storeDir(projectPath)).raw([
          '--git-dir',
          store,
          'worktree',
          'remove',
          '--force',
          worktreePath,
        ]);
      } catch (err) {
        log.warn(`removeWorktree: git removal failed for ${worktreePath}`, err);
        await fsPromises.rm(worktreePath, { recursive: true, force: true });
        await this.git(this.storeDir(projectPath))
          .raw(['--git-dir', store, 'worktree', 'prune'])
          .catch(() => undefined);
      }
    });
  }

  async retainSnapshot(projectPath: string, commitSha: string): Promise<void> {
    if (!/^[0-9a-f]{40}$/.test(commitSha))
      throw new Error('Invalid snapshot commit');
    await this.enqueue(projectPath, () =>
      this.git(this.storeDir(projectPath)).raw([
        '--git-dir',
        this.storeDir(projectPath),
        'update-ref',
        `refs/snapshots/${commitSha}`,
        commitSha,
      ]),
    );
  }

  async fsck(projectPath: string): Promise<void> {
    const store = this.storeDir(projectPath);
    await this.git(this.storeDir(projectPath)).raw([
      '--git-dir',
      store,
      'fsck',
      '--no-progress',
    ]);
  }

  private git(cwd: string, indexFile?: string): SimpleGit {
    const git = simpleGit(cwd, GIT_OPTS);
    if (!indexFile) return git;
    return git.env({
      ...(process.env.PATH ? { PATH: process.env.PATH } : {}),
      ...(process.env.HOME ? { HOME: process.env.HOME } : {}),
      [STORE_INDEX_FILE_ENV]: indexFile,
    });
  }

  private async ensureStore(projectPath: string): Promise<string> {
    const store = this.storeDir(projectPath);
    if (this.hasStore(projectPath)) return store;
    await fsPromises.mkdir(store, { recursive: true });
    await this.git(path.dirname(store)).raw([
      'init',
      '--bare',
      '--quiet',
      store,
    ]);
    const excludePath = path.join(store, 'info', 'exclude');
    await fsPromises.mkdir(path.dirname(excludePath), { recursive: true });
    await fsPromises.writeFile(
      excludePath,
      `${STORE_EXCLUDES.join('\n')}\n`,
      'utf8',
    );
    log.info(`Initialized variant tree store at ${store}`);
    return store;
  }

  private enqueue<T>(projectPath: string, task: () => Promise<T>): Promise<T> {
    const key = this.storeDir(projectPath);
    const prior = this.opQueues.get(key) ?? Promise.resolve();
    const current = prior.catch(() => undefined).then(task);
    this.opQueues.set(key, current);
    void current
      .catch(() => undefined)
      .finally(() => {
        if (this.opQueues.get(key) === current) {
          this.opQueues.delete(key);
        }
      });
    return current;
  }
}
